import hashlib

def generate_wordlist():
    names = ['Aaron', 'aaron', 'AARON']
    wordlist = []

    for year in range(1960, 2001):
        for month in range(1, 13):
            for day in range(1, 32):
                date = f"{year}{month:02d}{day:02d}"
                for name in names:
                    wordlist.append(f"{name}{date}")
                    wordlist.append(f"{date}{name}")
    return wordlist

def crack_hash(target_hash):
    wordlist = generate_wordlist()
    for word in wordlist:
        if hashlib.md5(word.encode()).hexdigest() == target_hash:
            return word
    return None

target = "7f4986da7d7b52fa81f98278e6ec9dcb"
